import type { CompanyInput } from "@/lib/schema";

/**
 * Y Combinator companies whose stated work is cancer, from the open YC directory dataset
 * (https://github.com/yc-oss/api, `companies/all.json`), filtered on industry, tags and description keywords and
 * then checked one by one against the YC profile and the company website on 2026-09-10. The full list of hits,
 * including the ones left out and why, is in `src/data/universe-lists/yc-oncology.json`.
 *
 * Conventions: `stage` follows the YC status (Active + Early = startup, Active + Growth = growth, Public, Acquired,
 * Inactive = defunct). Every record names Y Combinator as an investor; other investors only where the YC profile or
 * the company site states them. No round amounts unless a fetched source states them. Where the company website was
 * offline at the check, the YC profile stands in as the website and the summary says so.
 */

const asOf = "2026-09-10";
const yc = (slug: string) => `https://www.ycombinator.com/companies/${slug}`;

type Y = Omit<CompanyInput, "kind" | "asOf" | "companyType" | "investors" | "links"> & { slug: string; companyType?: CompanyInput["companyType"]; investors?: string[]; links?: CompanyInput["links"] };
const y = ({ slug, companyType = "biotech", investors = [], links = [], ...x }: Y): CompanyInput => ({
  kind: "company", asOf, companyType, investors: ["y-combinator", ...investors],
  links: [{ label: "Y Combinator profile", url: yc(slug) }, ...(x.website.startsWith("https://www.ycombinator.com") ? [] : [{ label: "Official website", url: x.website }]), ...links],
  tags: ["yc", ...(x.tags ?? [])],
  ...x,
});

